#include "mesh.h"#include "FileStuff.h"#include "BMP.h"OSErr getPassability ( FSSpec theMeshFSSpec );OSErr getPassability ( FSSpec theMeshFSSpec ){//----------------------------------vars-------------------------------------------------- 	short		theMeshFileRef;	OSErr		theError;	char *theMap;	int i, j, k, x, y;	long meshSize, meshWidth, meshHeight;	long PictureSize, PictureWidth, PictureHeight;	Myth256Palette thePalette;	picturePalette thePicturePalette[256]	= 		{			{ 0, 0, 0, 0, },			{ 240, 0, 0, 0, },			{ 180, 0, 0, 0, },			{ 128, 0, 0, 0, },			{ 34, 100, 180, 0, },			{ 11, 47, 109, 0, },			{ 43, 188, 107, 0, },			{ 130, 193, 190, 0, },			{ 160, 160, 160, 0, },			{ 0, 78, 0, 0, },			{ 240, 240, 240, 0, },			{ 0, 148, 0, 0, },			{ 255, 0, 209, 0, },			{ 33, 137, 255, 0, },			{ 0, 242, 253, 0, },			{ 0, 0, 255, 0, }		};	meshHeader theMeshHeader;	gridData *theGrid;//----------------------------------------------------------------------------------------		theError = FSpOpenDF ( &theMeshFSSpec, fsCurPerm, &theMeshFileRef );	if ( theError != noErr )		return theError;	FileRead ( &theMeshHeader, sizeof(struct meshHeader), theMeshFileRef );	meshWidth = theMeshHeader.meshWidth * 16;	meshHeight = theMeshHeader.meshHeight * 16;	meshSize =  meshWidth * meshHeight;	PictureWidth = meshWidth * 16;	PictureHeight = meshHeight * 16;	PictureSize = PictureWidth * PictureHeight;	// make the palette	for (i = 0; i < 16; i++){		thePalette.color[i].blue = thePicturePalette[i].blue;		thePalette.color[i].green = thePicturePalette[i].green;		thePalette.color[i].red = thePicturePalette[i].red;	}	for (i = 16; i < 256; i++){		thePalette.color[i].blue = i;		thePalette.color[i].green = i;		thePalette.color[i].red = i;	}	theGrid = (struct gridData *) NewPtr (meshSize * sizeof(gridData));	if ( theGrid == nil ){		FSClose ( theMeshFileRef );		return -1;	}	theMap = (char *) NewPtr (PictureSize);	if ( theMap == nil ){		DisposePtr ( (Ptr) theGrid );		FSClose ( theMeshFileRef );		return -1;	}		FileSeek ( theMeshFileRef, 1088L );	FileRead ( theGrid, theMeshHeader.meshLength, theMeshFileRef );	FSClose ( theMeshFileRef );	for ( y = 0, i = 0; y < PictureHeight - 1; y += 32, i += meshWidth ){		for ( x = PictureWidth - 32; x >= 0; x -= 32, i += 2 ){			for ( k = 0; k < 16; k++ ){				for ( j = 0; j < 16 - k; j++ )					theMap[x + y * PictureWidth + j + k * PictureWidth] = theGrid[i + 1].passability & 0x0F;				for ( j = 15; j > 15 - k; j-- )					theMap[x + y * PictureWidth + j + k * PictureWidth] = (theGrid[i + 1].passability >> 4) & 0x0F;				for ( j = k; j < 16; j++ )					theMap[x + 16 + y * PictureWidth + j + k * PictureWidth] = (theGrid[i].passability >> 4) & 0x0F;				for ( j = 0; j < k; j++ )					theMap[x + 16 + y * PictureWidth + j + k * PictureWidth] = theGrid[i].passability & 0x0F;				for ( j = k; j < 16; j++ )					theMap[x + (y + 16) * PictureWidth + j + k * PictureWidth] = (theGrid[i + meshWidth + 1].passability >> 4) & 0x0F;				for ( j = 0; j < k; j++ )					theMap[x + (y + 16) * PictureWidth + j + k * PictureWidth] = theGrid[i + meshWidth + 1].passability & 0x0F;				for ( j = 0; j < 16 - k; j++ )					theMap[x + 16 + (y + 16) * PictureWidth + j + k * PictureWidth] = theGrid[i + meshWidth].passability & 0x0F;				for ( j = 15; j > 15 - k; j-- )					theMap[x + 16 + (y + 16) * PictureWidth + j + k * PictureWidth] = (theGrid[i + meshWidth].passability >> 4) & 0x0F;			}		}	}	theError = writeBMP( "\p:Graphics.out:passability.bmp", PictureWidth, PictureHeight, &thePalette, theMap );	DisposePtr ( (Ptr) theMap );	DisposePtr ( (Ptr) theGrid );	return theError;}